"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[99],{46348:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"SkillTreeService","desc":"Permanent skill upgrade tree \u2014 a persistent coin sink. Lobby only:\\nplayers buy `SkillTreeData` nodes with coins; owned nodes save to\\n`profile.skillNodes` and replicate to the client through the normal\\nprofile replica (the tree UI reads `ClientState.playerData.skillNodes`).\\n\\nPrerequisites are validated server-side (`SkillTreeData.canBuy`) \u2014 a\\nclient asking for a node whose parents aren\'t owned is rejected before\\nany coins move.\\n\\nEffects (`SkillTreeData.effect`):\\n- health, speed, jump: applied to every character on spawn, but only\\n  where the humanoid still holds the default. A minigame that sets its\\n  own WalkSpeed or JumpPower for fairness keeps it.\\n- regen: a once-a-second heal, skipped on characters whose round set\\n  `HealthRegen` false.\\n- coin_bonus, xp_bonus: `rewardMultiplier`, read by BaseGameMode\'s\\n  payout. `defaultWalkSpeed` lets `SetPlayerSpeed` restore the boosted\\n  default.\\n\\nGated behind `FeatureFlags.SkillTree`: with it off, `init` binds no\\nhandlers, so `BUY_SKILL_NODE` gets no reply, and every effect is 0.","source":{"line":29,"path":"src/Server/Features/SkillTree/SkillTreeService.luau"}}')}}]);